  "@id": "https://naomedical.com/#nao-completion-faq",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What does triage mean when I am choosing care?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Triage means assessing and sorting care needs to determine urgency and the appropriate place of treatment. It helps decide which problem needs attention first; it is not a complete diagnosis. Describe your symptoms and how they have changed when asking for guidance. Call 911 for a life-threatening emergency rather than waiting for a routine clinic appointment."
      }
    },
    {
      "@type": "Question",
      "name": "How do I choose urgent care versus a regular primary clinician?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Use a regular primary clinician for prevention, chronic conditions and a continuing treatment plan. Urgent care can assess a stable new illness or minor injury that needs prompt attention. It should not replace ongoing follow-up. Severe breathing trouble, concerning chest pain, stroke symptoms, loss of consciousness or a severe allergic reaction needs emergency care; call 911."
      }
    }
  ]
}

